function replaceSection(
  html: string,
  id: string,
  nextId: string | null,
  replacement: string,
): string {
  const start = html.indexOf('<section id="' + id + '"');
  const end =
    start >= 0
      ? nextId
        ? html.indexOf('<section id="' + nextId + '"', start)
        : html.indexOf("</main>", start)
      : -1;
  if (start < 0 || end < 0) return html;
  return html.slice(0, start) + replacement + "\n\n" + html.slice(end);
}

export function applyCorePagesCanonical(html: string): string {
  let out = html;
  out = replaceSection(
    out,
    "page-overview",
    "page-providers",
    SECTIONS.overview,
  );
  out = replaceSection(
    out,
    "page-providers",
    "page-models",
    SECTIONS.providers,
  );
  out = replaceSection(out, "page-models", "page-mcp-tools", SECTIONS.models);
  out = replaceSection(out, "page-mcp-tools", "page-routing", SECTIONS.tools);
  out = replaceSection(out, "page-routing", "page-health", SECTIONS.routing);
  out = replaceSection(out, "page-health", "page-usage", SECTIONS.health);
  out = out.replace(
    "</head>",
    "<style>" + CORE_PAGES_CANONICAL_CSS + "</style></head>",
  );
  out = out.replace(
    "</body>",
    "<script>" + CORE_PAGES_CANONICAL_SCRIPT + "</script></body>",
  );
  return out;
}
